package routing

// costClassRank maps cost class to numeric rank (lower = cheaper).
var costClassRank = map[string]int{
	"local":        0,
	"cheap":        1,
	"medium":       2,
	"expensive":    3,
	"experimental": -1,
	"":             2, // unknown = medium
}

const StickyAffinityBonus = 250.0
const unknownUtilizationPenalty = 5.0
const unknownPerformancePenalty = 5.0

// scorePolicy returns a score for a candidate under the named profile.
// Higher is better.
//
// Routing priority policy (ported from DDx routing.go):
//   - cheap: local + low-cost preferred; subscription-within-quota next.
//   - standard: balanced; light local/subscription preference to avoid spend.
//   - smart: quality first; cloud capability wins; no local bonus.
//
// The policy is profile-aware AND provider-aware via providerBias hooks
// supplied by the caller (cooldown demotion, observation perf bias,
// provider-affinity bias).
func scorePolicy(profile string, cand candidateInternal) float64 {
	total := 0.0
	for _, component := range scoreComponents(profile, cand) {
		total += component
	}
	return total
}

func scoreComponents(profile string, cand candidateInternal) map[string]float64 {
	components := map[string]float64{
		"base":                100,
		"cost":                0,
		"deployment_locality": 0,
		"quota_health":        0,
		"utilization":         0,
		"performance":         0,
		"power":               0,
		"context_headroom":    0,
		"sticky_affinity":     0,
	}
	base := 100.0
	cr := costClassRank[cand.CostClass]
	withinQuota := cand.IsSubscription && cand.QuotaOK
	add := func(name string, value float64) {
		if value == 0 {
			return
		}
		components[name] += value
	}

	switch profile {
	case "cheap":
		if cand.CostClass == "local" {
			base += 40
			add("deployment_locality", 40)
		} else if withinQuota {
			base += 20
			add("quota_health", 20)
		}
		base -= float64(cr) * 30
		add("cost", -float64(cr)*30)

	case "standard":
		if cand.CostClass == "local" {
			base += 25
			add("deployment_locality", 25)
		} else if withinQuota {
			base += 15
			add("quota_health", 15)
		}
		base -= float64(cr) * 10
		add("cost", -float64(cr)*10)

	case "smart":
		// Quality first; higher cost rank approximates higher capability.
		base += float64(cr) * 20
		add("cost", float64(cr)*20)
		if withinQuota {
			base += 5
			add("quota_health", 5)
		}

	default:
		// Treat unspecified as standard.
		if cand.CostClass == "local" {
			base += 25
			add("deployment_locality", 25)
		} else if withinQuota {
			base += 15
			add("quota_health", 15)
		}
		base -= float64(cr) * 10
		add("cost", -float64(cr)*10)
	}

	// Provider preference bias.
	switch cand.ProviderPreference {
	case "local-first", "":
		if cand.CostClass == "local" {
			base += 30
			add("deployment_locality", 30)
		}
	case "subscription-first":
		if cand.IsSubscription && cand.QuotaOK {
			base += 30
			add("quota_health", 30)
		}
	}

	// Quota signals.
	if cand.IsSubscription {
		// Stale quota penalty.
		if cand.QuotaStale {
			base -= 15
			add("quota_health", -15)
		}

		// Trend-based adjustments.
		switch cand.QuotaTrend {
		case "exhausting":
			base -= 40
			add("quota_health", -40)
		case "burning":
			base -= 20
			add("quota_health", -20)
		case "healthy":
			base += 10
			add("quota_health", 10)
		}

		// Quota near-limit penalty (>= 80% used).
		if cand.QuotaPercentUsed >= 80 {
			penalty := float64(cand.QuotaPercentUsed-80) * 2
			base -= penalty
			add("quota_health", -penalty)
		}
	}

	// Historical success-rate adjustment (only when sufficient samples).
	if cand.HistoricalSuccessRate >= 0 {
		switch {
		case cand.HistoricalSuccessRate >= 0.8:
			base += 20
			add("quota_health", 20)
		case cand.HistoricalSuccessRate < 0.5:
			base -= 30
			add("quota_health", -30)
		}
	}
	if cand.ProviderSuccessRate >= 0 {
		switch {
		case cand.ProviderSuccessRate >= 0.8:
			base += 25
			add("quota_health", 25)
		case cand.ProviderSuccessRate < 0.5:
			base -= 35
			add("quota_health", -35)
		}
	}

	// Cooldown demotion: candidate has had recent failures.
	if cand.InCooldown {
		base -= 50
		add("quota_health", -50)
	}

	// Sticky affinity is a bonus after eligibility, not a hard pin.
	if cand.StickyMatch {
		base += StickyAffinityBonus
		add("sticky_affinity", StickyAffinityBonus)
	}

	// Utilization pressure can outweigh stickiness when the chosen server is
	// already busy or saturated.
	// Unknown or stale utilization is treated explicitly. Missing data gets a
	// small penalty so it cannot outrank a peer with real healthy evidence by
	// accident.
	if cand.EndpointSaturated {
		base -= 300
		add("utilization", -300)
	}
	if cand.EndpointLoad > 0 {
		loadPenalty := cand.EndpointLoad * 10
		if cand.EndpointLoadFresh {
			loadPenalty *= 2
		} else {
			loadPenalty += unknownUtilizationPenalty
		}
		if loadPenalty > 60 {
			loadPenalty = 60
		}
		base -= loadPenalty
		add("utilization", -loadPenalty)
	} else if !cand.EndpointLoadFresh {
		base -= unknownUtilizationPenalty
		add("utilization", -unknownUtilizationPenalty)
	}

	// Provider affinity: explicit provider pins are filtered before scoring;
	// this bonus only affects the ordering among still-eligible candidates
	// that share the pinned provider identity.
	if cand.ProviderAffinityMatch {
		base += 15
		add("deployment_locality", 15)
	}

	if cand.Power > 0 {
		base += float64(cand.Power) * 12
		add("power", float64(cand.Power)*12)
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens > 0 {
		costPenalty := cand.CostUSDPer1kTokens * 500
		if costPenalty > 60 {
			costPenalty = 60
		}
		base -= costPenalty
		add("cost", -costPenalty)
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens == 0 {
		switch {
		case cand.CostClass == "local":
			base += 15
			add("cost", 15)
		case cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80:
			base += 15
			add("quota_health", 15)
		}
	}
	if cand.Power >= 9 && cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80 {
		base += 20
		add("power", 20)
	}

	// Context headroom is a ranking signal for otherwise eligible candidates.
	// A larger spare window gives the model more room for completion and tool
	// overhead, so reward it modestly without overpowering the primary policy.
	if cand.ContextHeadroom > 0 {
		headroomBonus := float64(cand.ContextHeadroom) / 1000.0
		if headroomBonus > 30 {
			headroomBonus = 30
		}
		base += headroomBonus
		add("context_headroom", headroomBonus)
	}

	// Observation-derived perf bias.
	havePerfSignal := false
	if cand.ObservedTokensPerSec > 0 {
		// Small additive bonus, scaled.
		bonus := cand.ObservedTokensPerSec / 100.0
		base += bonus
		add("performance", bonus)
		havePerfSignal = true

package routing

import "testing"

func TestResolvePenalizesUnknownUtilizationAndPerformance(t *testing.T) {
	in := Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "fiz",
				CostClass:           "local",
				AutoRoutingEligible: true,
				Available:           true,
				ExactPinSupport:     true,
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{Name: "known", DefaultModel: "model-a", CostClass: "local", SupportsTools: true},
					{Name: "unknown", DefaultModel: "model-a", CostClass: "local", SupportsTools: true},
				},
			},
		},
		ModelEligibility: func(model string) (ModelEligibility, bool) {
			if model != "model-a" {
				return ModelEligibility{}, false
			}
			return ModelEligibility{Power: 7, AutoRoutable: true}, true
		},
		EndpointLoadResolver: func(provider, endpoint, model string) (EndpointLoad, bool) {
			if provider != "known" || model != "model-a" {
				return EndpointLoad{}, false
			}
			return EndpointLoad{NormalizedLoad: 0.1, UtilizationFresh: true}, true
		},
		ObservedSpeedTPS: map[string]float64{
			ProviderModelKey("known", "", "model-a"): 90,
		},
		ObservedLatencyMS: map[string]float64{
			ProviderModelKey("known", "", "model-a"): 100,
		},
	}

	dec, err := Resolve(Request{Harness: "fiz", Model: "model-a"}, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if len(dec.Candidates) != 2 {
		t.Fatalf("Candidates=%d, want 2", len(dec.Candidates))
	}
	var known, unknown Candidate
	for _, c := range dec.Candidates {
		switch c.Provider {
		case "known":
			known = c
		case "unknown":
			unknown = c
		}
	}
	if known.Provider != "known" || unknown.Provider != "unknown" {
		t.Fatalf("candidates=%+v, want known and unknown providers", dec.Candidates)
	}
	if known.Score <= unknown.Score {
		t.Fatalf("known score %.1f should beat unknown score %.1f", known.Score, unknown.Score)
	}
	if known.ScoreComponents == nil || unknown.ScoreComponents == nil {
		t.Fatalf("score components must be populated: known=%v unknown=%v", known.ScoreComponents, unknown.ScoreComponents)
	}
	for _, key := range []string{"base", "cost", "deployment_locality", "quota_health", "utilization", "performance", "power", "context_headroom", "sticky_affinity"} {
		if _, ok := known.ScoreComponents[key]; !ok {
			t.Fatalf("known score components missing %q: %+v", key, known.ScoreComponents)
		}
		if _, ok := unknown.ScoreComponents[key]; !ok {
			t.Fatalf("unknown score components missing %q: %+v", key, unknown.ScoreComponents)
		}
	}
	if known.Utilization <= 0 {
		t.Fatalf("known utilization component=%v, want positive known load", known.Utilization)
	}
	if unknown.Utilization != 0 {
		t.Fatalf("unknown utilization component=%v, want 0 for unknown load", unknown.Utilization)
	}
	if known.ScoreComponents["utilization"] == 0 {
		t.Fatalf("known utilization score component=%v, want explicit known-load adjustment", known.ScoreComponents["utilization"])
	}
	if unknown.ScoreComponents["utilization"] >= 0 {
		t.Fatalf("unknown utilization score component=%v, want explicit penalty", unknown.ScoreComponents["utilization"])
	}
	if known.ScoreComponents["performance"] <= 0 {
		t.Fatalf("known performance score component=%v, want positive known performance", known.ScoreComponents["performance"])
	}
	if unknown.ScoreComponents["performance"] >= 0 {
		t.Fatalf("unknown performance score component=%v, want explicit penalty", unknown.ScoreComponents["performance"])
	}
	if known.StickyAffinity != 0 || unknown.StickyAffinity != 0 {
		t.Fatalf("unexpected sticky affinity components: known=%v unknown=%v", known.StickyAffinity, unknown.StickyAffinity)
	}
	if dec.Provider != "known" {
		t.Fatalf("winner provider=%q, want known", dec.Provider)
	}
}

func TestResolveReportsStickyAffinityComponentWhenStickyKeyMatches(t *testing.T) {
	in := Inputs{
